import{_ as a,o as t,c as s,ak as i}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Design System: Chainy team board","description":"Creative North Star: \\"Chainy team workspace\\"","frontmatter":{"title":"Design System: Chainy team board","description":"Creative North Star: \\"Chainy team workspace\\"","source":"DESIGN.md","category":"Other documents","sourceUpdated":"2026-10-13T02:10:44+08:00","outline":[2,3]},"headers":[],"relativePath":"content/design.md","filePath":"content/design.md"}'),o={name:"content/design.md"};function r(n,e,d,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i('<div><h1 id="design-system-chainy-team-board">Design System: Chainy team board<a class="header-anchor" href="#design-system-chainy-team-board" aria-label="Link to this section">​</a></h1><h2 id="overview">Overview<a class="header-anchor" href="#overview" aria-label="Link to this section">​</a></h2><p><strong>Creative North Star: &quot;Chainy team workspace&quot;</strong></p><p>A light, compact workspace with dark readable text, familiar task controls and the existing Chainy logo and blue-led palette. Names, dates and visible states carry meaning; role colors support the names.</p><p>This record captures the implemented team board only. Its visual authority is the existing documentation identity in <code>tools/docs-viewer/site/.vitepress/theme/brand.css</code>; the board uses the exact values recorded above. The user-specified Trello-style direction is recorded in <code>tools/team-board/direction.md</code>. No replacement brand or unchosen creative concept is introduced.</p><p><strong>Key Characteristics:</strong></p><ul><li>Light canvas, white working surfaces and restrained blue emphasis.</li><li>Descriptive task titles with named leads and dates.</li><li>Compact controls, visible focus and direct editing alternatives to dragging.</li></ul><h2 id="colors">Colors<a class="header-anchor" href="#colors" aria-label="Link to this section">​</a></h2><p>The inherited palette combines blue emphasis, cool neutral surfaces and soft role colors. Frontmatter values are normative; <code>board.css</code> is the implementation source.</p><ul><li><strong>Primary:</strong> <code>blue</code> identifies primary actions, active navigation, links, focus-related drag feedback and form accents; <code>blue-dark</code> is the primary hover state.</li><li><strong>Supporting roles:</strong> the five named surface/ink pairs identify people. Sherwin uses blue, Christian violet, Luis warm orange, Sean green and Miguel rose. Timeline bars use related, separately implemented shades; completed bars use <code>done-surface</code> and muted text.</li><li><strong>Neutral:</strong> <code>ink</code> carries primary text, <code>muted</code> supports labels and dates, <code>canvas</code> is the page, <code>white</code> is the working surface, and <code>line</code> separates regions. The column and navigation surfaces provide grouping without heavy depth.</li><li><strong>States:</strong> <code>danger</code> signals destructive actions and errors. <code>focus</code> marks keyboard focus. Amber prerequisite notices and amber/violet fixed-event markers supplement explicit text; they do not change task status.</li></ul><p><strong>The Preview Ramp Rule.</strong> The sidecar&#39;s tonal ramps are synthesized panel previews. Use the recorded frontmatter colors and implemented component colors in the interface.</p><h2 id="typography">Typography<a class="header-anchor" href="#typography" aria-label="Link to this section">​</a></h2><p>Use the system UI stack in the frontmatter, with Segoe UI first. No external font is required. The display role belongs to the sign-in welcome; the headline belongs to the workspace heading; title belongs to card names. Body and label roles describe the common explicit sizes, not a universal reset.</p><p>Card names are the strongest content within cards. Supporting names, dates and history metadata are smaller. Dates use tabular numerals where implemented. Preserve sentence case, natural wrapping and visible labels. The implementation has no fixed typographic scale ratio.</p><h2 id="layout">Layout<a class="header-anchor" href="#layout" aria-label="Link to this section">​</a></h2><p>The board uses the full workspace width with desktop side padding (32px). A compact header, fixed-event strip, page heading, navigation and wrapping filters precede the task area. The Board has three columns: To do, In progress and Done. Desktop columns are equal width with a minimum (270px), a gap (20px), inner padding (15px) and a minimum height (320px).</p><p>At the medium breakpoint (1000px and below), side padding becomes (20px), column minimum width (260px), gap (14px), and the content area can scroll horizontally. At the phone breakpoint (600px and below), side padding becomes (15px), each board column is <code>calc(100vw - 57px)</code> with a gap (12px); all three remain in one horizontal board. Search becomes full width, navigation occupies its own row and filters wrap. The workspace label is hidden. Trash changes from three to two to one column. Sign-in changes from two columns to a vertical layout.</p><p>The task drawer is right-aligned, full-height and capped by the viewport width. It becomes full width on narrower phones. At the phone breakpoint its inner padding becomes (22px 20px 28px), and task, password and sign-in fields use a readable mobile size (16px).</p><p>Timeline keeps task labels sticky at the left and dates sticky at the top. Label width is (290px), changing to (160px) on phones. Its scroll area is capped at (64vh), or (65vh) on phones. Day widths are (30px) for the pre-final window and (13px) for the whole project. The default window is October 12-November 22, 2026; whole-project view starts with October 12, 2026-April 9, 2027 and expands to include task dates. These are current schedule settings, not permanent design tokens.</p><h2 id="elevation--depth">Elevation &amp; Depth<a class="header-anchor" href="#elevation--depth" aria-label="Link to this section">​</a></h2><p>White cards and fields sit on tinted regions with thin borders. Cards have no resting shadow; hover changes the border and raises them slightly (1px). The only explicit shadows are the active timeline drag (<code>0 4px 12px #233a5833</code>) and feedback toast (<code>0 5px 18px #162c4226</code>). The modal backdrop (<code>#122a4680</code>) separates focused editing from the workspace. Exact shadow and motion extensions are also recorded in the sidecar.</p><h2 id="shapes">Shapes<a class="header-anchor" href="#shapes" aria-label="Link to this section">​</a></h2><p>Use the frontmatter radius roles: gently rounded surfaces and cards, smaller corners for controls and bars, and circular avatars. The task drawer has a straight viewport edge; the password and sign-in surfaces have their own softer corners. Borders are ordinarily thin (1px); active navigation uses an underline (3px). External-link and close icons are inline, current-color SVG strokes, with decorative SVGs hidden from assistive technology and the close button explicitly named.</p><h2 id="components">Components<a class="header-anchor" href="#components" aria-label="Link to this section">​</a></h2><ul><li><strong>Buttons and navigation:</strong> blue primary actions; white secondary controls; blue text controls; red destructive text. Most buttons have a minimum height (40px), with compact header and phone variants. Disabled buttons dim and show a waiting cursor. Keyboard focus uses an outline (3px) with offset (3px). Active view buttons expose <code>aria-current=&quot;page&quot;</code> and a blue underline; retain the Board, Timeline, History and Trash labels.</li><li><strong>Fields:</strong> visible labels, white backgrounds and defined borders. Search has an accessible hidden label. Textareas resize vertically. Errors appear next to the affected form with alert semantics; prerequisite warnings use a separate notice. Support and prerequisites use named checkbox groups.</li><li><strong>Task cards:</strong> the card body opens its details and labels that action visibly; a separate move grip starts dragging. Title comes first, then named lead and dates; a prerequisite note appears when relevant. Dragging dims the source, tints the destination column and outlines the insertion target. The task drawer offers status plus a card-order select: keep position, move to top/bottom or place before a named task. This preserves ordering without a drag gesture.</li><li><strong>Task and password dialogs:</strong> native modal dialogs are named by their visible headings. Task editing includes lead, dates, acceptance, an editable checklist of up to 50 steps, prerequisites, evidence, references, issue link and card history. Checklist changes stay in the protected board and are recorded in card history. Escape and close dismiss task editing unless saving. An archived task is read-only and offers Restore; archiving preserves history. Initial password setup requires completion or sign-out; later changes can be cancelled.</li><li><strong>Timeline:</strong> named task-label buttons and focusable bars open the same task drawer; Enter or Space opens a bar. Moving a bar shifts both dates; dragging either edge adjusts one date. Exact date fields remain available. Fixed beta (November 3-6, 2026) and pre-final defense (November 21, 2026) have their own event row and cannot be moved as tasks.</li><li><strong>History and feedback:</strong> history shows actor, task, surface, Manila time and expandable changes, with earlier entries loaded on request. Connection text distinguishes saving, up to date, pending/retrying GitHub copy and offline failure. Saved messages follow successful shared-board writes. Toasts last (4 seconds), or (10 seconds) for errors. Refresh checks run every (10 seconds) while eligible; failed edits restore saved state or retain the form error for correction.</li><li><strong>Motion:</strong> drawer entry translates from the right (30px) and fades from partial opacity over (0.2s ease-out). Column and card feedback use short transitions (0.15s). Reduced-motion preference disables animations and transitions and restores automatic scroll behavior.</li></ul><h2 id="dos-and-donts">Do&#39;s and Don&#39;ts<a class="header-anchor" href="#dos-and-donts" aria-label="Link to this section">​</a></h2><h3 id="do">Do:<a class="header-anchor" href="#do" aria-label="Link to this section">​</a></h3><ul><li>Do preserve the Chainy logo, documentation relationship and implemented light palette.</li><li>Do pair role colors with names and status colors with text.</li><li>Do keep task names readable and fixed school events distinct from editable planning dates.</li><li>Do preserve visible keyboard focus, named dialogs and the status, order and date fields as alternatives to dragging.</li></ul><h3 id="dont">Don&#39;t:<a class="header-anchor" href="#dont" aria-label="Link to this section">​</a></h3><ul><li>Don&#39;t lead the interface with internal task codes or infer completion percentages from task counts.</li><li>Don&#39;t report an unsaved change as saved or hide connection errors.</li><li>Don&#39;t add decorative motion or reinterpret role colors as progress.</li></ul></div>',1)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
